// ❌ TodoList định danh row bằng INDEX của mảng
type Todo = { text: string; done: boolean };

function TodoList() {
  const [todos, setTodos] = useState<Todo[]>([
    { text: 'Học JavaScript', done: true },
    { text: 'Học React', done: false },
    { text: 'Học Next.js', done: false },
  ]);

  // Thêm việc mới lên ĐẦU danh sách → mọi index dịch +1
  const addFirst = (text: string) => setTodos([{ text, done: false }, ...todos]);

  return (
    <ul>
      {todos.map((todo, index) => (
        <TodoRow key={index} todo={todo} />  // ❌ key theo VỊ TRÍ
      ))}
      <button onClick={() => addFirst('Nộp báo cáo')}>+ Việc khẩn</button>
    </ul>
  );
}

